(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["その他"]=[{"id":"00002498","register_sub_id":"101","register_pk":"103488","name":"あさでん春光整備工場（旧陸軍第七師団騎兵第七連隊覆馬場）","kana":"あさでんしゅんこうせいびこうじょう（きゅうりくぐんだいななしだんきへいだいななれんたいおおいばば）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道旭川市春光3条7丁目231","lat":43.802921,"lng":142.370697,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"煉瓦造平屋建、鉄板葺、建築面積1174㎡","structure_material":"煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0045","desc":"市街北部に位置する。積雪時の軍馬訓練用に作られた切妻造煉瓦建造物。用途を考慮して，良好な換気と採光が意図され，越屋根や屋根窓等の開口部を多く設ける。控え壁付の柱に，鉄製フィンクトラス架構が載り，建築面積１０００㎡超の大空間を創り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002498"},{"id":"00013012","register_sub_id":"101","register_pk":"368325","name":"函館公園こどものくに空中観覧車","kana":"はこだてこうえんこどものくにくうちゅうかんらんしゃ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"北海道","address":"北海道函館市青柳町17","lat":41.75625556,"lng":140.71635,"geo_status":"db","era":"昭和25年／昭和40年移設","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"鉄骨造、高さ10m、脚間2.2m","structure_material":"鉄骨造","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0155","desc":"函館公園こどものくににある観覧車。二本の支柱間に直径八メートルのホイールを取り付け、その外周に八台のゴンドラを吊り下げる。ホイールは二本背合せの山形鋼を放射状に配し、外周と中間二か所を山形鋼で八角形に繋ぐ。国内現存最古の観覧車として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013012"},{"id":"00003336","register_sub_id":"101","register_pk":"104326","name":"旧第八師団長官舎（弘前市長公舎）","kana":"きゅうだいはちしだんちょうかんしゃ（ひろさきしちょうこうしゃ）","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県弘前市大字上白銀町1-1","lat":40.602856,"lng":140.463165,"geo_status":"db","era":"大正6／昭和34移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"02 － 0016","desc":"弘前城の南方に位置するもと師団長官舎の洋館部。桁行８間半，梁間５間半，平入のハーフティンバー風洋館で，外壁はモルタル塗，妻面などに欄間付上げ下げ窓を配する。袴腰型屋根の前面３箇所にドーマー窓を設け，玄関部に切妻破風をつくる。堀江組の施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003336"},{"id":"00011435","register_sub_id":"101","register_pk":"210406","name":"旧陸軍省軍馬補充部六原支部官舎第一棟","kana":"きゅうりくぐんしょうぐんばほじゅうぶろくはらしぶかんしゃだいいちとう","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県胆沢郡金ケ崎町六原蟹子沢17-1","lat":39.233285,"lng":141.050816,"geo_status":"db","era":"明治44年頃／平成27年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"03-0089","desc":"軍馬の育成から供給までを行うため置かれた軍馬補充部の官舎。洋風下見板張の外観で、中廊下を挟んで東列は和室とし、西列に洋風の応接室を配する。玄関を二箇所設ける構成は、軍馬への乗降を考慮したものと思われる。現存例の少ない佐官級のための旧陸軍官舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011435"},{"id":"00011437","register_sub_id":"101","register_pk":"210408","name":"旧陸軍省軍馬補充部六原支部官舎第三棟","kana":"きゅうりくぐんしょうぐんばほじゅうぶろくはらしぶかんしゃだいさんとう","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県胆沢郡金ケ崎町六原蟹子沢16","lat":39.233866,"lng":141.050348,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"03-0091","desc":"第二棟の北側に東西棟で建つ。木造平屋建、寄棟造鋼板葺で間取りは第二棟と同様。イギリス積の煉瓦基礎や外壁の下見板張、上げ下げ窓やモールディングの付いた額縁など共通した洋風意匠を見せる。第二棟と同じく第一棟に比べやや簡素な構成をとる旧陸軍官舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011437"},{"id":"00011436","register_sub_id":"101","register_pk":"210407","name":"旧陸軍省軍馬補充部六原支部官舎第二棟","kana":"きゅうりくぐんしょうぐんばほじゅうぶろくはらしぶかんしゃだいにとう","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県胆沢郡金ケ崎町六原蟹子沢16","lat":39.233603,"lng":141.050219,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"03-0090","desc":"第一棟と道路を挟んで西側に東西棟で建つ。木造平屋建、寄棟造鋼板葺。北面に玄関を設け中廊下を通して東側に応接間、南側に和室を配するなど採光にも配慮した間取りで、台所、浴室等は北西にまとめる。年代が明らかで、やや簡素な構成をとる官舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011436"},{"id":"00010907","register_sub_id":"101","register_pk":"208634","name":"延命寺山門","kana":"えんめいじさんもん","category":"その他","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県白石市字不澄ケ池68-1","lat":38.007639,"lng":140.624408,"geo_status":"db","era":"江戸後期／明治7頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"04-0120","desc":"延命寺は白石城下の北東に境内を構える。山門は三間一戸門、木造二階建で、櫓門の形式となり、白石城厩口門を移築したと伝わる。櫓部は白漆喰で塗込め、正面には縦格子付の格狭間二所を開く。白石城の希少な遺構として、白石の歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010907"},{"id":"00005234","register_sub_id":"101","register_pk":"106222","name":"旧奈良家住宅北野小休所","kana":"きゅうならけじゅうたくきたのしょうきゅうじょ","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市金足小泉字上前8","lat":39.823246,"lng":140.064713,"geo_status":"db","era":"明治14／明治後期・昭和62移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積54㎡、塔屋付","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"05 － 0136","desc":"敷地の西辺に位置する。桁行５間，梁間３間の木造平屋建で，寄棟造の屋根北寄りに入母屋造，楼状の塔屋を載せる。内部は４畳半上段に６畳座敷を続け，一枚板の縁を巡らす。縁の外側は土縁とし，外周に雨戸を建て込む。当家の歴史の一端を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005234"},{"id":"00002742","register_sub_id":"101","register_pk":"103732","name":"安積疏水麓山の飛瀑","kana":"あさかそすいはやまのひばく","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県郡山市麓山1-347・348","lat":37.393974,"lng":140.375458,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"石造、堤長14m、堤高8m、水路延長23m付","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0065","desc":"猪苗代湖から引かれた安積疏水の最終地点，麓山公園の一角に築かれた石造構造物。約１．８ｍの越流部を突起付石積柱で挟み込み，その両脇に土留壁，底部に水叩き及び水路を石造で築く。明治を代表する国家的開拓事業の一つ安積疏水事業の記念碑的建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002742"},{"id":"00002737","register_sub_id":"101","register_pk":"103727","name":"千歳館客室つる","kana":"ちとせかんきゃくしつつる","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県山形市七日町四丁目107-2他","lat":38.25368972,"lng":140.34305911,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0045","desc":"敷地の南東隅に建つ離れで，昭和２年に山形市で開催された全国産業博覧会の舞台を移築したとも伝えられる。１２畳の座敷に床棚，書院を設け，西面と北面に広縁を廻らす。屋根は勾配の緩い入母屋造，鉄板葺で，他の２棟とともに庭園を囲んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002737"},{"id":"00001556","register_sub_id":"101","register_pk":"102546","name":"宇都宮中央女子高校赤レンガ倉庫（旧第六十六歩兵連隊倉庫）","kana":"うつのみやちゅうおうじょしこうこうあかれんがそうこ（きゅうだいろくじゅうろくほへいれんたいそうこ）","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市若草2-101-18の外","lat":36.581367,"lng":139.859894,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"煉瓦造平屋建、鉄板葺、建築面積248㎡","structure_material":"煉瓦造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"09 － 0023","desc":"明治４０年の宇都宮への第１４師団設置に伴い，第６６歩兵連隊の厨房関係施設として建設され，現在は倉庫に用いられている。切妻造・平屋建で，外壁がイギリス積み煉瓦造，小屋組は木造トラスである。宇都宮に残る軍事関連施設のうち，唯一の明治期の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001556"},{"id":"00002511","register_sub_id":"101","register_pk":"103501","name":"旧東村花輪小学校今泉嘉一郎胸像所","kana":"きゅうあずまむらはなわしょうがっこういまいずみかいちろうきょうぞうしょ","category":"その他","subcategory":"その他工作物","type_guess":"記念碑・像","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県みどり市東町花輪191","lat":36.52235735,"lng":139.30953517,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造、面積28㎡、前面階段付","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0088","desc":"校舎建設費を寄付した今泉嘉一郎の古希を記念した胸像及び顕彰碑銘板の設置所。平面は十字形で，正面に階段を設け花崗石製の高欄を側面まで廻し，背面は壁を造って左右に銘板を嵌込み，胸像の後ろには切妻破風を立上げる構成。設計は工科大学同期の伊東忠太。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002511"},{"id":"00001899","register_sub_id":"101","register_pk":"102889","name":"高崎白衣大観音像","kana":"たかさきびゃくえだいかんのんぞう","category":"その他","subcategory":"その他工作物","type_guess":"記念碑・像","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県高崎市石原町金澤山2710-1","lat":36.31095707,"lng":138.98073808,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造、高さ42m、台座付","structure_material":"鉄筋コンクリート造","registered":"2000.10.18(平成12.10.18)","register_no":"10 － 0043","desc":"井上工業初代社長井上保三郎の発意で観音山頂に建設された高さ４１ｍの鉄筋コンクリート造観音像。ラーメン構造の本体に，外壁ブロックを緊結し，白セメントで仕上げる。９層よりなる内部に計２０体の胎内仏を祀る。高崎のランドマーク的存在として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001899"},{"id":"00006664","register_sub_id":"101","register_pk":"107647","name":"前橋市中央児童遊園（るなぱあく）もくば館","kana":"まえばししちゅうおうじどうゆうえん（るなぱあく）もくばかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県前橋市大手町3-16-3","lat":36.39519338,"lng":139.06329105,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積8.3㎡、電動木馬5基付","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0246","desc":"前橋市中心部に位置する前橋市中央児童遊園入口近くに建つ。間口４．５ｍ奥行１．８ｍ規模、片流れ屋根で、外装は竪板張とする。正面は吹放ちで、前面に木製階段を付け、内部には５基の電動木馬を配する。現存最古級の電動木馬と一体的に残る遊園施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006664"},{"id":"00003067","register_sub_id":"101","register_pk":"104057","name":"旧東京第二陸軍造兵廠深谷製造所給水塔","kana":"きゅうとうきょうだいにりくぐんぞうへいしょうふかやせいぞうしょきゅうすいとう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県深谷市原郷1118","lat":36.19826523,"lng":139.30451102,"geo_status":"db","era":"昭和19頃","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"鉄筋コンクリート造、高さ18m、面積41㎡","structure_material":"鉄筋コンクリート造","registered":"2003.01.31(平成15.01.31)","register_no":"11 － 0046","desc":"周辺の軍施設に給水するために建設された塔で，一時期は松根油を採取する装置も設けられていた。内部は５層構造で，昭和３０年以降は住宅として改造された。鉄筋コンクリートのラーメン構造が外観にそのまま現れており，その特異な外観で知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003067"},{"id":"00005255","register_sub_id":"101","register_pk":"106243","name":"細淵家住宅長屋門","kana":"ほそぶちけじゅうたくながやもん","category":"その他","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県さいたま市南区沼影1-17-8","lat":35.84353842,"lng":139.64477759,"geo_status":"db","era":"江戸後期／明治期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0093","desc":"屋敷東辺に建ち，南北棟の切妻造，桟瓦葺で，南半を門口，北半を部屋とする。門口は出桁造で中央に扉を吊り北端に潜戸を設ける。欅材を用い，乳金具や八双金具等も多く，武家門の重厚感がある。岩槻城からの移築という伝承は，形式や細部から，信頼性が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005255"},{"id":"00001848","register_sub_id":"101","register_pk":"102838","name":"坂長本店袖蔵（旧古河城乾蔵）","kana":"さかちょうほんてんそでぐら（きゅうこがじょういぬいぐら）","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.192745,"lng":139.704086,"geo_status":"db","era":"文久3","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0030","desc":"四つ辻の角地に位置する２階建の土蔵で，隣接する店藏と棟を直交して建つ。外壁は白漆喰塗り，屋根は切妻造，桟瓦葺とする。古河城乾藏を移築したものと伝え，牛梁に「文久三年癸亥五月吉日」の記がある。店蔵とともに古河城を偲ぶ数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001848"},{"id":"00001847","register_sub_id":"101","register_pk":"102837","name":"坂長本店店蔵（旧古河城文庫蔵）","kana":"さかちょうほんてんみせぐら（きゅうこがじょうぶんこぐら）","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.19261228,"lng":139.70421104,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0029","desc":"間口４間，奥行３間の土蔵造２階建の店舗で，１階正面に土庇が付く。四周に半間毎に柱を立てた構造で，１階は大引天井とする。明治６年の廃城令によって古河城が解体・売却された際に，旧文庫蔵を移築したものと伝え，構造や意匠に旧規を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001847"},{"id":"00002606","register_sub_id":"101","register_pk":"103596","name":"旧陸軍演習場内圍壁","kana":"きゅうりくぐんえんしゅうじょうないいへき","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県習志野市東習志野4-15-6","lat":35.69500587,"lng":140.0752884,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造、延長20m、鉄筋コンクリート造2階建付","structure_material":"鉄筋コンクリート造","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0041","desc":"長２０ｍ，高３．３ｍ，厚３０ｃｍほどの鉄筋コンクリート造壁と３ｍ角平面の２階建望楼部から成る。壁体部には２段に銃眼が穿たれ，東寄りにアーチ状の入口を開ける。入口上部の扁額状銘板から年代と工兵第一大隊による築造が知られる。演習場遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002606"},{"id":"00000758","register_sub_id":"101","register_pk":"101748","name":"千葉工業大学通用門（旧鉄道第二連隊表門）","kana":"ちばこうぎょうだいがくつうようもん（きゅうてつどうだいにれんたいおもてもん）","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県習志野市津田沼2-17-1","lat":35.68966359,"lng":140.02188532,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造門柱４基からなる，幅10.6m","structure_material":"煉瓦造門柱４基からなる","registered":"1998.09.02(平成10.09.02)","register_no":"12 － 0007","desc":"明治４３年移駐の陸軍鉄道連隊第三大隊（大正７年鉄道第二連隊に改組）の表門。鉄道連隊関係施設で現存する数少ないもののひとつで，煉瓦造の４本の門柱が残る。土地の歴史を知る上で貴重な建造物で，現在は「工大の煉瓦門」の愛称で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000758"},{"id":"00002370","register_sub_id":"101","register_pk":"103360","name":"寛永寺渋沢家霊堂","kana":"かんえいじしぶさわけれいどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木1-14-11","lat":35.721706,"lng":139.774979,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0112","desc":"渋沢栄一前妻の１７回忌にあわせて建設と伝える。桁行４間半，梁行４間半，宝形造，瓦葺で，正面は両開桟唐戸，その左右に花頭窓が付き，柱上に舟形肘木を載せる。軒は一軒疎垂木。内部の内陣境の欄間彫刻，杉板小壁や杉戸等の彩色画に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002370"},{"id":"00012881","register_sub_id":"101","register_pk":"367989","name":"旧九段会館","kana":"きゅうくだんかいかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区九段南一丁目5-1","lat":35.69437778,"lng":139.75139167,"geo_status":"db","era":"昭和9年／昭和32年・同58年・平成30年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造4階地下1階建、瓦葺、建築面積1620㎡","structure_material":"鉄骨鉄筋コンクリート造4階地下1階建","registered":"2019.09.10(令和1.09.10)","register_no":"13 － 421","desc":"内堀通りに建つ鉄骨鉄筋コンクリート造4階建の複合施設。軍人会館として競技設計1等案をもとに建てられた。通り沿いは両端に城郭風の入母屋造塔屋を戴く歴史主義の和風表現を基調に、要所にアール・デコの手法を取り入れる。九段下の街路景観の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012881"},{"id":"00000951","register_sub_id":"101","register_pk":"101941","name":"東京水産大学雲鷹丸","kana":"とうきょうすいさんだいがくうんようまる","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都港区港南4-5-7","lat":35.62512542,"lng":139.74919461,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鋼製帆船，長さ41.2m，最大幅8.7m","structure_material":"鋼製帆船","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0042","desc":"東京水産大学の前身である農商務省水産講習所の練習船として大阪鉄工所桜島工場で建造された。３本マストのバーク型「鋼製補助機関付」帆船で，国産鋼製船舶としては現存最古のものになる。昭和３７年，大学のシンボルとして喫水線上部が現位置に移設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000951"},{"id":"00008668","register_sub_id":"101","register_pk":"149389","name":"弥彦公園トンネル","kana":"やひここうえんとんねる","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦字御殿山667-1他","lat":37.69970212,"lng":138.82796037,"geo_status":"db","era":"大正7年／昭和62年改修","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造、延長55m、幅員3.1m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0341","desc":"園内中央西側に位置する小山に設けられる。馬蹄形アーチ断面になる煉瓦造の歩行者用トンネルで、延長55ｍを測る。坑門はアーチ周縁や壁柱、笠石を花崗岩で造り、壁面を煉瓦で化粧する。造営時の気風を伝える象徴的な公園施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008668"},{"id":"00011280","register_sub_id":"101","register_pk":"209116","name":"石川県立美術館広坂別館（旧陸軍第九師団長官舎）","kana":"いしかわけんりつびじゅつかんひろさかべっかん（きゅうりくぐんだいきゅうしだんちょうかんしゃ）","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市出羽町1","lat":36.560873,"lng":136.660743,"geo_status":"db","era":"大正11／昭和中期・同63・平成27改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0257","desc":"兼六園南方に建つもと師団長官舎の洋館部。正面はハーフティンバー調とし、車寄を張り出す。半切妻の大屋根を架け、平側に切妻破風を突出させて特徴とする。内部では応接室や旧食堂の暖炉飾などに当初の意匠を残す。大正期軍官舎の通例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011280"},{"id":"00000405","register_sub_id":"101","register_pk":"101395","name":"旧陸軍金沢偕行社","kana":"きゅうりくぐんかなざわかいこうしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市出羽町7他","lat":36.55919167,"lng":136.66164444,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建，瓦葺，建築面積282㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"17 － 0006","desc":"マンサ－ド風の屋根を持つ中央棟の左右に，寄棟の翼屋が付く構造になる。コリント式のピラスターやドーマー窓等バロック風の技巧的な装飾を用いた外観意匠は，全体として華やかで優れている。明治４２年に現在地に移築したと伝える。設計は，陸軍経理部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000405"},{"id":"00000404","register_sub_id":"101","register_pk":"101394","name":"旧陸軍第九師団司令部庁舎","kana":"きゅうりくぐんだいきゅうしだんしれいぶちょうしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市出羽町7他","lat":36.55894167,"lng":136.66181667,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建，瓦葺，建築面積275㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"17 － 0005","desc":"左右対称型の構成になり，正面のペディメントやピラスタ－，上下窓など簡素なルネサンス風の外観を見せる。明治期の庁舎建築の好例。旧金沢城内に建築されたが，昭和４５年に現在地に移築され，その際両翼の一部が切り縮められた。設計は，陸軍経理部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000404"},{"id":"00003960","register_sub_id":"101","register_pk":"104950","name":"中村神社拝殿（旧金沢城二の丸能舞台）","kana":"なかむらじんじゃはいでん（きゅうかなざわじょうにのまるのうぶたい）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市中村町16-1","lat":36.561203,"lng":136.644455,"geo_status":"db","era":"江戸末期／明治3・昭和40移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0090","desc":"金沢城二の丸能舞台を移築改造。方３間，４隅角柱上三斗組，二軒疎垂木，入母屋造，桟瓦葺で，正側面に刎高欄付切目縁を回し，外回りを双折桟唐戸，格子戸引違で仕切り内部は折上格天井とする。内法上の派手な蟇股や丸彫嵌め彫刻に往時の豪奢な姿をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003960"},{"id":"00005756","register_sub_id":"101","register_pk":"106744","name":"山梨大学赤レンガ館","kana":"やまなしだいがくあかれんがかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市北新1-4-2","lat":35.67871333,"lng":138.56776556,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積330㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"19 － 0055","desc":"歩兵４９連隊糧秣庫として建設。煉瓦造平屋建，切妻造，桟瓦葺で，桁行２０間，梁間５間規模。当初は桁行を４等分して間仕切り，各室の両側面と両妻面に櫛形アーチの戸口を設け，櫛形アーチの窓を開く。外壁は煉瓦のオランダ積。小屋組はキングポストトラス。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005756"},{"id":"00009276","register_sub_id":"101","register_pk":"194069","name":"旧松本歩兵第五十連隊糧秣庫（信州大学医学部資料室）","kana":"きゅうまつもとほへいだいごじゅうれんたいりょうまつこ（しんしゅうだいがくいがくぶしりょうしつ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県松本市旭3-696-1","lat":36.25115478,"lng":137.98017906,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積330㎡","structure_material":"煉瓦造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"20 － 0423","desc":"信州大学の敷地内に建ち、桁行三六・三メートル梁間九・一メートル、煉瓦造平屋建、切妻造桟瓦葺である。外壁はイギリス積で北面三箇所、西面一箇所の戸口を設け、欠円アーチ窓を開く。小屋組はキングポストトラスとする。校地の歴史を伝える煉瓦倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009276"},{"id":"00011133","register_sub_id":"101","register_pk":"205240","name":"西駒山荘石室","kana":"にしこまさんそういしむろ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県伊那市伊那7119-140","lat":35.806064,"lng":137.829458,"geo_status":"db","era":"大正4／大正15・昭和24・平成26改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造平屋建、鋼板葺、建築面積42㎡","structure_material":"石造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"20 - 0500","desc":"中央アルプス木曽駒ヶ岳の北東方、標高約二七〇〇メートルの稜線上に南北棟で建つ。大振りの花崗岩割石を布積した躯体に、キングポストトラスの小屋を組む。強風の吹く西側は軒下まで土砂で埋め、東側に小窓を穿つ。近代登山における石室式の山小屋の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011133"},{"id":"00002393","register_sub_id":"101","register_pk":"103383","name":"山田旅館薬師堂","kana":"やまだりょかんやくしどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.8622483,"lng":137.98068413,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0098","desc":"新館の東北方，浴室の北方の山際に南面して建つ。南北棟，入母屋造，もと茅葺，妻入で，方１間半程度の規模を有する。簡素な薬師堂であるが，病の療養にきた湯治客にとって祈願の施設が不可欠であったことを物語る建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002393"},{"id":"00004965","register_sub_id":"101","register_pk":"105955","name":"岐阜公園三重塔","kana":"ぎふこうえんさんじゅうのとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市槻谷13-2","lat":35.434681,"lng":136.77582626,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積24㎡","structure_material":"木造三重塔","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0058","desc":"石造二重基壇上に建つ木造三重塔。各層とも方三間で，円柱を立てて尾垂木付の三手先組物を配し，上層には刎高欄を廻す。軒は二軒繁垂木で，本瓦葺屋根を架ける。装飾を用いない古風な意匠で，設計は伊東忠太。金華山の西麓にあって広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004965"},{"id":"00005602","register_sub_id":"101","register_pk":"106590","name":"震災紀念堂","kana":"しんさいきねんどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市若宮町2-10","lat":35.4203,"lng":136.762024,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0089","desc":"市街地にあり，ほぼ南面して建つ。入母屋造，桟瓦葺，正面唐破風造の向拝付で，平面は外陣，内陣及び余間の構成になり，側廻りは角柱に舟肘木を載せる。震災紀念堂としては我が国最初のもので，外観，内部とも浄土真宗本堂形式を基調としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005602"},{"id":"00002627","register_sub_id":"101","register_pk":"103617","name":"凱旋紀念門","kana":"がいせんきねんもん","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町渋川","lat":34.92408914,"lng":137.68615525,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造、幅3.2m、高さ3.6m","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"22 － 0079","desc":"日露戦争を記念して，神社参道の途中に築かれた。石造柱脚の上に，柱頭を鋸歯飾とした煉瓦造柱が立ち上がり，煉瓦造欠円アーチを挟み込む。大型の扁額を嵌め込んだフランス積壁面の上部に，江戸切仕上石材の重厚な笠石を載せる。県内初期の煉瓦造構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002627"},{"id":"00000435","register_sub_id":"101","register_pk":"101425","name":"愛知大学旧本館（旧陸軍第15師団司令部庁舎）","kana":"あいちだいがくきゅうほんかん（きゅうくりぐんだいじゅうごしだんしれいぶちょうしゃ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県豊橋市町畑町1-1","lat":34.74009563,"lng":137.38648544,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1859㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"23 － 0009","desc":"木造２階建で，両翼屋を背後に突き出したコの字形平面をもつ。外壁に下見板を貼り，装飾をあまり用いない簡素なつくりで，縦長の上下窓を均等に配置するなど標準化の傾向がみられる。明治末期の陸軍による兵営建築の手法をよく示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000435"},{"id":"00005764","register_sub_id":"101","register_pk":"106752","name":"オリエンタルビル屋上観覧車","kana":"おりえんたるびるおくじょうかんらんしゃ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区栄3-5-1","lat":35.1685171,"lng":136.90593656,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄骨造、高さ12m、脚間6.2m","structure_material":"鉄骨造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0233","desc":"デパートの屋上に設置。二基の三角錐状鉄骨架構の支柱間に直径１０ｍの鉄骨製円形ホイールを取り付け，ホイール外周部に鉄骨製の４人乗ケージ９個を吊り下げる。娯楽遊戯施設の専門業者である東京の昭和鉄工株式会社が納入している。現存最古級の観覧車遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005764"},{"id":"00000214","register_sub_id":"101","register_pk":"101204","name":"乃木倉庫","kana":"のぎそうこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中区本丸1","lat":35.18618301,"lng":136.89748382,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"煉瓦造平屋建，瓦葺，建築面積91㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0005","desc":"乃木将軍が命じ５年頃に名古屋に赴任したことにちなんで名付けられたと伝える名古屋城御深井丸に位置する旧陸軍の火薬庫。煉瓦造、平屋建で、屋根を切妻造、桟瓦葺とする。角を石積み風に造り出す等の高度な技術に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000214"},{"id":"00003860","register_sub_id":"101","register_pk":"104850","name":"明治村歩兵第六聯隊兵舎","kana":"めいじむらほへいだいろくれんたいへいしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.343311,"lng":136.99086,"geo_status":"db","era":"明治6／昭和40移築","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積389㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0094","desc":"木造２階建，寄棟造。当初は桁行５０ｍを超える建物で，移築時に３分の２に縮めた。外壁は白漆喰塗の大壁に胴蛇腹を巡らせ，やや幅広の上げ下げ窓を開く。入口はポーチの起り屋根をトスカナ式円柱が支え，櫛形欄間付の唐戸を開く。鎮台時代兵舎建築の遺存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003860"},{"id":"00003888","register_sub_id":"101","register_pk":"104878","name":"旧北伊勢陸軍飛行場掩体","kana":"きゅうきたいせりくぐんひこうじょうえんたい","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県鈴鹿市三畑町5079-72","lat":34.90800299,"lng":136.49674467,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造、建築面積533㎡","structure_material":"鉄筋コンクリート造","registered":"2004.02.17(平成16.02.17)","register_no":"24 － 0049","desc":"旧北伊勢飛行場と近隣の航空機用施設とを結ぶ誘導路沿いに位置する。 鉄筋コンクリート造で，平面は正面幅２９．６ｍ奥行８．４ｍの長方形部分と，奥行１４．７ｍ最小幅９．１ｍの台形部分からなる。第二次世界大戦末期における中型規模の掩体の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003888"},{"id":"00002656","register_sub_id":"101","register_pk":"103646","name":"千里寺本堂","kana":"せんりじほんどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府吹田市千里山西1-37-42","lat":34.777363,"lng":135.505066,"geo_status":"db","era":"昭和3／昭和7移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積502㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0177","desc":"昭和天皇即位大礼の饗宴場の一部を転用したもの。桁行約３０ｍ，梁間約１７ｍ，入母屋造，本瓦葺，妻入で，東正面に４間の向拝を付す。移築・転用で改造も多いが，角柱を長押で固めた軸部，内部の二重折上格天井，照明器具等，近代宮殿建築の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002656"},{"id":"00002971","register_sub_id":"101","register_pk":"103961","name":"多木浜洋館記念碑","kana":"たきはまようかんきねんひ","category":"その他","subcategory":"その他工作物","type_guess":"記念碑・像","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加古川市別府町東町174","lat":34.72264363,"lng":134.84606792,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造、面積148㎡","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0109","desc":"主屋西北方に位置する。我国人造肥料製造の鼻祖で多木製肥所の創始者である多木久米次郎（1859～1942）の銅像所として建設。北木島産花崗石による簡潔かつ豪放な造形を有し，底面１４尺四方高１８尺の台石には時の総理大臣斎藤実の書による「肥料主」を刻む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002971"},{"id":"00003129","register_sub_id":"101","register_pk":"104119","name":"姫路市立美術館（旧第十師団兵器庫）","kana":"ひめじしりつびじゅつかん（きゅうだいじゅうしだんへいきこ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市本町68-25","lat":34.839703,"lng":134.696564,"geo_status":"db","era":"明治38頃／大正2増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積2923㎡","structure_material":"煉瓦造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0115","desc":"兵器庫として建てられた煉瓦造建築。南北棟の増築部分の設計は棟札より陸軍技手宮本平治，井田熊吉があたったことが知られる。一時期市庁舎として使用され，後に美術館となった。姫路城の一角にあって，姫路市の近代の歩みを示す建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003129"},{"id":"00013618","register_sub_id":"101","register_pk":"504895","name":"旧加太砲台厠","kana":"きゅうかだほうだいかわや","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市加太1907-2","lat":34.27045833,"lng":135.06746389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0288","desc":"弾廠の南に建つ切妻造の桟瓦葺である。南北両妻に階段を設けて中廊下とし、東側に仕切りなしで溝が連なる小便所、西側に八室の大便所である。小便所側は煉瓦積基礎を腰高まで積む。外壁は簓子下見板張で東西両面に無双窓を開く。類例少なく貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013618"},{"id":"00013617","register_sub_id":"101","register_pk":"504894","name":"旧加太砲台弾廠","kana":"きゅうかだほうだいだんしょう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市加太1907-2","lat":34.27071111,"lng":135.06730833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0287","desc":"大阪湾防衛のため紀淡海峡を望む山上に築かれた砲台の弾薬庫である。切妻造桟瓦葺の南北棟で三室に間仕切り、中央室は弾架を設けた作業場、北室と南室は詰所とみられる。キングポストトラスまで鉋仕上とした上質な造りを持つ。要塞の実相を伝えて貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013617"},{"id":"00000413","register_sub_id":"101","register_pk":"101403","name":"祇園閣","kana":"ぎおんかく","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側594-1","lat":35.00214625,"lng":135.7797585,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造・鉄骨鉄筋コンクリート造3階建，銅板葺，建築面積67㎡","structure_material":"鉄筋コンクリート造・鉄骨鉄筋コンクリート造3階建","registered":"1997.12.12(平成9.12.12)","register_no":"26 － 0010","desc":"大倉喜八郎の依頼により，伊東忠太が設計した普請道楽の一つ。施工大倉土木。総高約３４ｍの３階建塔状建築で，下層及び基礎部分を鉄筋コンクリート造，中層以上を鉄骨鉄筋コンクリートとする。山鉾をかたどった和風の外観，内部のグロテスク型の照明は特異。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000413"},{"id":"00010984","register_sub_id":"101","register_pk":"208954","name":"聖母女学院法人本館","kana":"せいぼじょがくいんほうじんほんかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市伏見区深草田谷町1","lat":34.958592,"lng":135.772376,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造2階建、銅板葺、建築面積879㎡","structure_material":"煉瓦造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"26-0499","desc":"もと陸軍第一六師団の司令部庁舎。長さ六〇メートルに及ぶ煉瓦造二階建で、正面中央はイオニア式の大オーダーとペディメントで威厳をもたせ、両翼はトスカナ式意匠とし、屋根に大小のドーマー窓を並べる。内部の階段なども上質。師団司令部庁舎の希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010984"},{"id":"00000159","register_sub_id":"101","register_pk":"101149","name":"島根県立浜田高等学校第二体育館（旧歩兵第21連隊雨覆練兵場）","kana":"しまねけんりつはまだこうとうがっこうだいにたいいくかん（きゅうほへいだいにじゅういちれんたいあめおおいれんぺいじょう）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県浜田市黒川町3749","lat":34.89908549,"lng":132.09675002,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建，スレート葺，建築面積644㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"32 － 0008","desc":"浜田市立第一中学校屋内運動場と同じく，旧陸軍の屋内練兵場の建物を再利用したもの。建築の年代は大正５年と新しいが，構造規模ともほぼ同様になる。県道の際にあり同窓生はもとより道行く人にも広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000159"},{"id":"00000158","register_sub_id":"101","register_pk":"101148","name":"浜田市立第一中学校屋内運動場（旧歩兵第21連隊雨覆練兵場）","kana":"はまだしりつだいいちちゅうがっこうおくないうんどうじょう（きゅうほへいだいにじゅういちれんたいあめおおいれんぺいじょう）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県浜田市黒川町3745","lat":34.90166841,"lng":132.09731103,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造平屋建，スレート葺，建築面積639㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"32 － 0007","desc":"煉瓦造，切妻造，波形鉄板葺，棟に明かり取りを兼ねた小屋根をかける。質素な外観ながら，小屋組にＬ型鋼のフィンクトラスを用いて室内空間を造り出す点は壮観である。山陰地方で煉瓦造及び鉄骨小屋組を用いた建造物の最初期の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000158"},{"id":"00009375","register_sub_id":"101","register_pk":"194168","name":"岡山県総合グラウンドクラブ（旧岡山偕行社）","kana":"おかやまけんそうごうぐらうんどくらぶ（きゅうおかやまかいこうしゃ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区いずみ町1-1","lat":34.67766925,"lng":133.91861439,"geo_status":"db","era":"明治43年／昭和25年改修・昭和43年・平成15年移築改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"33 － 0252","desc":"総合グラウンド南東部に東面して建つ。木造二階建、寄棟造桟瓦葺、桁行二三･七メートル梁間一〇・九メートル、正面左右に切妻の階段室を張出す。外観は半円ペディメントやイオニア式円柱を用いた古典様式で整える。現代的な運動公園に歴史的な彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009375"},{"id":"00006037","register_sub_id":"101","register_pk":"107022","name":"岡山大学情報展示室（旧陸軍第十七師団司令部衛兵所）","kana":"おかやまだいがくじょうほうてんじしつ（きゅうりくぐんだいじゅうななしだんしれいぶえいへいじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区津島中1-1-1","lat":34.68668569,"lng":133.919479,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0150","desc":"市街地北方に位置する岡山大学津島キャンパスの正門脇に建つ。桁行７．３ｍ，梁間５．５ｍ規模の寄棟造，平屋建で，平側に上下窓を配す。外壁はドイツ下見板張，腰縦板張とし，基礎は煉瓦積とする。小規模ながら丁寧なつくりで，正門廻りの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006037"},{"id":"00004179","register_sub_id":"101","register_pk":"105169","name":"野﨑武左衛門翁旌徳碑","kana":"のざきぶざえもんおうしょうとくひ","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47202102,"lng":133.80331988,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、高さ18m、台座面積66㎡","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0086","desc":"オベリスク型の記念碑。コンクリート基礎上に，約８ｍ四方の基壇を花崗岩で組み，その上方に上下２組の台座，さらに長１２ｍ一本石の尖角柱を立ち上げ全体高１８ｍとする。我国で珍しいエジプト趣味の建造物。設計はフランス帰りの土木技師山田寅吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004179"},{"id":"00004182","register_sub_id":"101","register_pk":"105172","name":"野﨑武左衛門翁旌徳碑石垣","kana":"のざきぶざえもんおうしょうとくひいしがき","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.46864242,"lng":133.80056877,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、延長128m","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0089","desc":"敷地の東面及び北面を囲む高さ１．１ｍ，折れ曲がり延長１２８ｍの石垣。台形縦断面を有する小型の石材を敷地正面の両端と中央部に計４基配する。敷地正面・側面の隅部を亀甲積，それ以外の部分を谷積とするなど，外観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004182"},{"id":"00004180","register_sub_id":"101","register_pk":"105170","name":"野﨑武左衛門翁旌徳碑石橋","kana":"のざきぶざえもんおうしょうとくひいしばし","category":"その他","subcategory":"土木構造物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47184246,"lng":133.80330402,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造桁橋、橋長4.4m、幅員2.0m","structure_material":"石造桁橋","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0087","desc":"旌徳碑の手前に位置し，敷地内の池に架けられた太鼓橋風の石造桁橋。表面ビシャン叩仕上の花崗岩を用い，橋長４．４ｍ，幅員２．０ｍとし，頂部を四角錐とした親柱を四隅に配する。縦断線形の湾曲を低く押さえ，旌徳碑へのパースペクティブ効果を高めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004180"},{"id":"00004181","register_sub_id":"101","register_pk":"105171","name":"野﨑武左衛門翁旌徳碑門柱","kana":"のざきぶざえもんおうしょうとくひもんちゅう","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47176254,"lng":133.80340854,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、高さ4.7m","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0088","desc":"旌徳碑の敷地の入口に配される。面取と浅彫が施された直方体の上部に，葉をかたどった凹状軒蛇腹風の装飾，さらには笠石，丸みを帯びた錘形の飾りを載せ，高さ４．７ｍとする。手の込んだ丁寧な造りで，オベリスクの意匠を意識した造形を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004181"},{"id":"00013337","register_sub_id":"101","register_pk":"366326","name":"旧江田島海軍下士卒集会所（海友舎）二階建棟","kana":"きゅうえたじまかいぐんかしそつしゅうかいしょ（かいゆうしゃ）にかいだてとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県江田島市江田島町中央二丁目17490","lat":34.24765833,"lng":132.47676667,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造二階建、瓦葺、建築面積83㎡","structure_material":"木造二階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0279","desc":"旧海軍下士卒の集会場の正面棟。木造二階建、寄棟造桟瓦葺で、正面中央部に切妻造の玄関ポーチをを張出し、二階にバルコニーを設ける。下見板張の外壁に上下窓を並べ、玄関ポーチの欄間や持送に意匠を凝らす。現存する希少な木造の下士卒集会所であり貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013337"},{"id":"00013338","register_sub_id":"101","register_pk":"366327","name":"旧江田島海軍下士卒集会所（海友舎）平屋建棟","kana":"きゅうえたじまかいぐんかしそつしゅうかいしょ（かいゆうしゃ）ひらやだてとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県江田島市江田島町中央二丁目17490","lat":34.24763889,"lng":132.47698333,"geo_status":"db","era":"明治38年／昭和3年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0280","desc":"二階建棟の東背面に建つ。明治38年に建てた旧呉海軍下士卒集会所桜松館を昭和３年に移築したもの。木造平屋建、寄棟造桟瓦葺で、平面はＬ字型で武道場と遊技室で構成する。二階建棟とともに木造の旧海軍下士卒集会所として希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013338"},{"id":"00009065","register_sub_id":"101","register_pk":"162425","name":"呉市入船山記念館旧高烏砲台火薬庫","kana":"くれしいりふねやまきねんかんきゅうたかからすほうだいかやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市幸町1-1","lat":34.2398757,"lng":132.56470241,"geo_status":"db","era":"明治35年／昭和42年移築","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積41㎡","structure_material":"石造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"34 － 0124","desc":"南北棟の切妻造桟瓦葺。桁行９．７ｍ梁間４．２ｍ、瘤出し仕上げの花崗岩を積み上げ、西面中央に欠円アーチの出入口を開ける。東・西面に二所、南・北面中央に一所の矩形窓を穿つ。妻床下には欠円アーチを設け、換気に配慮する。重厚な倉庫の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009065"},{"id":"00000903","register_sub_id":"101","register_pk":"101893","name":"呉市水道局二河水源地取入口","kana":"くれしすいどうきょくにこうすいげんちとりいれぐち","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市大字荘山田村字東二河平甲1653-1","lat":34.26766462,"lng":132.55761862,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造，延長11.8m","structure_material":"石造","registered":"1998.10.09(平成10.10.09)","register_no":"34 － 0020","desc":"呉鎮守府の軍用水道施設のひとつ。宮原浄水場に導水するために二河峡にある水源地につくられた石造の坑門で，上部に「呉鎮守府水道」と刻まれた標石を置く。アーチ形の開口部両脇に柱型をあらわした丁寧なつくりで，我が国初期の水道施設のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000903"},{"id":"00000901","register_sub_id":"101","register_pk":"101891","name":"呉市水道局宮原浄水場低区配水池","kana":"くれしすいどうきょくみやはらじょうすいじょうていくはいすいち","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市青山町5-2","lat":34.2373444,"lng":132.56693984,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"煉瓦造，幅37m，長さ44.4m","structure_material":"煉瓦造","registered":"1998.10.09(平成10.10.09)","register_no":"34 － 0018","desc":"呉鎮守府の軍用水道は，横浜，函館に続き我が国で３番目にできた水道施設で，宮原浄水場はそのひとつとしてつくられた。配水池の容量は 8,000立米で，煉瓦造の上屋を設ける。簡素ながら我が国初期の水道施設の様子を知る上で貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000901"},{"id":"00016435","register_sub_id":"101","register_pk":"536502","name":"呉ＹＷＣＡ会館","kana":"くれわいだぶりゅしーえーかいかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県呉市幸町2-1","lat":34.24157778,"lng":132.56584722,"geo_status":"db","era":"昭和前期／昭和53年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積294㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0324","desc":"呉港東の高台に建つＹＷＣＡの会館。敷地に合わせたＶ字平面で２階建切妻造鉄板葺、外壁下見板張。隅切部に縦長窓を開けて吹抜ホールとし、踊場付階段で二階へ上る。二階床の合成梁など特徴的な構法を用い、角地に建つ洋風の外観が地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016435"},{"id":"00003311","register_sub_id":"101","register_pk":"104301","name":"飛弾家住宅観音堂","kana":"ひだけじゅうたくかんのんどう","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.18090208,"lng":132.85452165,"geo_status":"db","era":"明治初期／大正末期移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0041","desc":"蔵門南側に並んで建つ。道路側の東を正面とした小規模な仏堂で，平面は１辺３ｍで，正面に庇柱を立て，本瓦葺屋根は宝形造とし，正面に庇を葺き降ろす。外壁が真壁造と簡素であるが，屋敷側床下を当家の墓所とするなど，当地の信仰形態が伺える数少ない事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003311"},{"id":"00007403","register_sub_id":"101","register_pk":"108385","name":"周南市市長公舎洋館","kana":"しゅうなんししちょうこうしゃようかん","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市慶万町1821-2","lat":34.050526,"lng":131.814148,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0062","desc":"細長い敷地の後方に位置する。急勾配の切妻屋根の妻壁を西正面に見せ、その北に南北棟の切妻屋根を２段に設ける。腰に煉瓦、その上に黄土色の化粧タイルを貼り、上部はハーフティンバー風とする。内部は玄関と応接間等からなる。穏やかな外観になる洋館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007403"},{"id":"00007404","register_sub_id":"101","register_pk":"108386","name":"周南市市長公舎和館","kana":"しゅうなんししちょうこうしゃわかん","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市慶万町1821-2","lat":34.050461,"lng":131.814331,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0063","desc":"洋館の東に接して建つ。東西棟の寄棟造を主棟に、落棟の切妻屋根や寄棟屋根、両下屋根を出し、変化に富む屋根構成を見せる。トコや棚、平書院を構える十畳の座敷や次の間を西側に設け、東には中廊下で、浴室や台所ほか私的な居室を配する。良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007404"},{"id":"00004424","register_sub_id":"101","register_pk":"105414","name":"安藝家バラッケ（旧板東俘虜収容所）","kana":"あきけばらっけ（きゅうばんどうふりょしゅうようじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町桧字椎尾谷37","lat":34.16816157,"lng":134.49256573,"geo_status":"db","era":"大正6／昭和43移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"36 － 0048","desc":"桁行１５間梁間４間，木造平屋建，切妻造，桟瓦葺である。現在は改造され農業用倉庫となっているが，当初は桁行４０間の規模を有し，内部は中央の土間通路を挟み，左右に低い板床を張って２間毎に間仕切られていた。簡素な建物であるが，軍関係営舎の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004424"},{"id":"00004425","register_sub_id":"101","register_pk":"105415","name":"柿本家バラッケ（旧板東俘虜収容所）","kana":"かきもとけばらっけ（きゅうばんどうふりょしゅうようじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町桧字東山田53","lat":34.16386667,"lng":134.49884167,"geo_status":"db","era":"大正6／昭和43移築／平成18移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"36 － 0049","desc":"桁行１５間梁間４間，木造平屋建，切妻造，スレート葺である。当初は桁行４０間の規模を有し，内部は中央の土間通路を挟み，左右に低い板床を張って２間毎に間仕切られていた。簡素な建物であるが，軍関係営舎の一例。平成18年に道の駅「第九の里」公園内に移築されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004425"},{"id":"00002686","register_sub_id":"101","register_pk":"103676","name":"旧陸軍第一一師団兵舎棟","kana":"きゅうりくぐんだいじゅういちしだんへいしゃとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市文京町3-2-1","lat":34.226288,"lng":133.781784,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積878㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0084","desc":"四国学院大学キャンパスの西北方に位置し２号館校舎として使用。桁行５８．５ｍ，梁行１５ｍ規模，桟瓦葺，寄棟造の木造２階建兵舎で，南面中央に１本石によるロマネスク風大オーダーと大振りなペディメントにより類例のない玄関ポーチを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002686"},{"id":"00016742","register_sub_id":"101","register_pk":"579226","name":"明治天皇丸亀行在所址碑","kana":"めいじてんのうまるがめあんざいしょあとひ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県丸亀市大手町二丁目1-5","lat":34.289906,"lng":133.799597,"geo_status":"db","era":"大正11年／昭和47年・令和元年移築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"石造、高さ7.8m、基壇付","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"37 - 0496","desc":"丸亀護国神社境内に建つ明治天皇の行幸記念碑。総高７・８メートル。基壇中央の台座に立つ花崗岩製角柱頂部に銅製鳳凰像を飾る。角柱正面に碑文、上端に円形と紐を組合わせた装飾を付す。装飾抑えつつ格調を高めた外観で、地元の寄付金を用いて建てた記念碑。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016742"},{"id":"00005377","register_sub_id":"101","register_pk":"106365","name":"山田家（旧清酒源氏正宗醸造元）儀兵衛地蔵堂","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）ぎへえじぞうどう","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼字落合3129","lat":34.35297837,"lng":134.12952026,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積2.3㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0297","desc":"四国霊場八十五番札所八栗寺の表古参道に位置し，山田家長屋門の西南方に北面して建つ。方１間，宝形造，桟瓦葺の堂で，内部に享保１４年と明和２年を刻む地蔵２体を安置する。外壁３面の腰は縦板張，上部漆喰塗とした簡素な堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005377"},{"id":"00002463","register_sub_id":"101","register_pk":"103453","name":"山田家（旧清酒源氏正宗醸造元）灯篭","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）とうろう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.3524928,"lng":134.13018646,"geo_status":"db","era":"弘化5","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"石造、高さ3.0m","structure_material":"石造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0079","desc":"屋敷地へのアプローチ道路入口に建つ常夜燈。聖天さんと親しまれる八栗寺参道沿いに在って八栗寺への道しるべとなる。胴部の参道沿いの南面には施主である主人「山田徳右衛門」の名を，東面には「聖天舎」を刻んで建立の由来を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002463"},{"id":"00002183","register_sub_id":"101","register_pk":"103173","name":"梅錦山川仕込蔵","kana":"うめにしきやまかわしこみぐら","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県四国中央市金田町金川14","lat":33.98895346,"lng":133.59402327,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積184㎡","structure_material":"土蔵造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0014","desc":"主屋の南方に建つ南北棟，寄棟造，本瓦葺のやや規模の大きな平入の仕込蔵で，西面を旧道沿いに，南面を金生川支流三角寺川沿いにみせる。腰を竪板張りとし，小さな開口を２段千鳥に配して特徴ある正面をつくる。もと伊予西条藩御船蔵を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002183"},{"id":"00002313","register_sub_id":"101","register_pk":"103303","name":"鍵谷カナ頌功堂","kana":"かぎやかなしょうこうどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市西垣生町1253","lat":33.81327024,"lng":132.70400284,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積39㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"38 － 0017","desc":"伊予絣創始者の鍵谷カナの功績を讃え伊予織物同業組合が建設。設計は木子七郎。鉄筋コンクリート造の八角堂で，中央に頌功碑を納める。８本のエンタシスの柱と斗組により反りの強い本瓦葺八角屋根を支える特徴的な姿形をしていることで知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002313"},{"id":"00003723","register_sub_id":"101","register_pk":"104713","name":"旧正野谷桟橋","kana":"きゅうしょうのだにさんばし","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県西宇和郡伊方町正野地先","lat":33.35896696,"lng":132.03507641,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造及び石造、延長73m","structure_material":"鉄筋コンクリート造及び石造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0052","desc":"町南西部の佐田岬先端近くで宇和海に突き出た旧軍用桟橋。計２４本の円柱に支えられ，表面をモルタル洗出しとした係船柱付のＲＣ造構造物が，緑泥変岩を矢筈積風とした石垣と接続し，接続部の橋台上には花崗岩を配す。軍艦波止の愛称で住民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003723"},{"id":"00003150","register_sub_id":"101","register_pk":"104140","name":"旧鈍川小学校二宮金次郎像台座","kana":"きゅうにぶかわしょうがっこうにのみやきんじろうぞうだいざ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県今治市玉川町鈍川丙245-1","lat":33.98567772,"lng":132.95744724,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造及びコンクリート造、面積7.5㎡","structure_material":"石造及びコンクリート造","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0027","desc":"鈍川運動公園の一角に建つ。当時の校長，教師，児童が学校下の玉川から川原石を拾い集め，富士山状に積み上げたもの。底辺４ｍ，高３ｍ規模の玉石練積の三角錐状台座で，正面に「恩」の字を刻んだレリーフを積み込む。鈍川地区のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003150"},{"id":"00014541","register_sub_id":"101","register_pk":"513955","name":"旧陸軍歩兵第四四連隊講堂","kana":"きゅうりくぐんほへいだいよんじゅうよんれんたいこうどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県高知市曙町二丁目960-3","lat":33.54923056,"lng":133.48400278,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0307","desc":"市西部の旧陸軍跡地に東面して建つ。木造平屋建、寄棟造平入で、外装は下見板張白色塗装とする。小屋組はキングポスト・トラス、内壁は竪板張目板打、一間幅の窓を密に配して採光を確保する。当初は３室に分かれ、下士官の学科教育用に建てた質実な陸軍建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014541"},{"id":"00014540","register_sub_id":"101","register_pk":"513954","name":"旧陸軍歩兵第四四連隊弾薬庫","kana":"きゅうりくぐんほへいだいよんじゅうよんれんたいだんやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県高知市曙町二丁目960-3","lat":33.54988889,"lng":133.48409167,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺、建築面積156㎡","structure_material":"煉瓦造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0306","desc":"市西部の旧陸軍跡地に東面して建つ。煉瓦造平屋建、寄棟造平入、正面板壁と引戸の下屋を付す。外壁約五〇センチ厚、内部は板張天井で板敷の三室を並べ、高床として湿気を抑え、出入口の欠円アーチ形両開き戸を鉄板で覆う。ほぼ完存する貴重な明治期の弾薬庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014540"},{"id":"00004442","register_sub_id":"101","register_pk":"105432","name":"料亭得月楼客間","kana":"りょうていとくげつろうきゃくま","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高知市南はりまや町1-17-3","lat":33.558846,"lng":133.544235,"geo_status":"db","era":"昭和12／昭和25移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0156","desc":"本館の東南方に位置し，待合いを兼ねた渡り廊下で連絡する。桁行４間半梁間４間半，切妻造，桟瓦葺の木造平屋建で，南妻面を庭園に見せて建つ。６畳と８畳座敷から成り，北に便所と納戸を配し，四周に半間廊下を廻す。もと南国博覧会の営林局出品館を移築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004442"},{"id":"00015110","register_sub_id":"101","register_pk":"529388","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場観測所","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうかんそくしょ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島174","lat":33.04814722,"lng":129.84388333,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造2階建、建築面積19㎡","structure_material":"煉瓦造及び鉄筋コンクリート造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0145","desc":"発射場が位置する片島の山頂に位置し、魚雷試射後の雷跡を観測する建物。二階建の煉瓦壁体の頂部に鉄筋コンクリート造の梁とスラブを廻らし、二階正面には広角に開いた観測用の窓を突出して海を望む。建物の機能を直裁的に造形化した特徴的な外観の軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015110"},{"id":"00015108","register_sub_id":"101","register_pk":"529386","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場機械室及び水雷調整室","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうきかいしつおよびすいらいちょうせいしつ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島151-1","lat":33.04898333,"lng":129.842775,"geo_status":"db","era":"大正7年頃／昭和14年増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造及び煉瓦造平屋建、建築面積330㎡","structure_material":"石造及び煉瓦造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0143","desc":"突堤と正対して建ち、魚雷用の燃料及び酸化剤などを搭載し、調整した施設。正面一二メートル、奥行二七メートルで、下部は石造で内部を水雷調整室と機械室の二室に区画する。上部は後の増築で壁体を鉱滓煉瓦積とする。機能と建設技術において貴重な軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015108"},{"id":"00015106","register_sub_id":"101","register_pk":"529384","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場射場","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうしゃじょう","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島地先","lat":33.04893333,"lng":129.84190556,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"発射場 コンクリート造、面積276㎡、発射場上屋付（煉瓦造及び鉄筋コンクリート造3階建、建築面積6.5㎡）","structure_material":"発射場 コンクリート造","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0141","desc":"大村湾北部に位置する旧魚雷試射専用施設。陸地から約五〇メートル離れた海中に、コンクリートブロックで構築した矩形の人工島で、魚雷発射用の切込みを設け、煉瓦壁体と鉄筋コンクリート造屋根スラブ等からなる上屋や軌道敷を残す。全国的に希少な軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015106"},{"id":"00015107","register_sub_id":"101","register_pk":"529385","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場突堤","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうとってい","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島地先","lat":33.04899167,"lng":129.84221389,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"コンクリート造5連アーチ橋、橋長45m、幅員3.6m","structure_material":"コンクリート造5連アーチ橋","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0142","desc":"射場と陸地を結ぶために海中に築いた突堤。形状の異なるコンクリートブロックで積み上げた、長さ四五メートル、スパン八メートルの扁平な五連アーチ構造物。天端には二線の引込線跡を残す。コンクリートブロックを自在に成形して築いた独特な大規模構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015107"},{"id":"00015109","register_sub_id":"101","register_pk":"529387","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場油庫","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうゆこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島174","lat":33.048725,"lng":129.84269722,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、建築面積20㎡","structure_material":"石造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0144","desc":"機械室及び水雷調整室の南側に建つ燃料用の格納庫。桁行五・五メートル、梁間三・七メートル、切妻造、妻入の石造平屋建で、内壁はモルタル塗で仕上げる。凝灰岩を精緻に積上げ、隅部を算木積で築く、丁寧なつくり。魚雷試射システムに欠かせない施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015109"},{"id":"00010381","register_sub_id":"101","register_pk":"199153","name":"金剛庫","kana":"こんごうこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘13-3","lat":33.373307,"lng":129.553016,"geo_status":"db","era":"江戸末期／明治前期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積100㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0119","desc":"松浦史料博物館の北方に南北棟で南面して建つ。二階建の土蔵で、桁行五間梁間二間半、切妻造桟瓦葺とし、正面入口に下屋を設ける。外壁は竪板張で、正面の扉には鉄板を張る。城内の土蔵を移築したと伝わり、藩政期の平戸城に由来する希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010381"},{"id":"00000420","register_sub_id":"101","register_pk":"101410","name":"佐世保市民文化ホール（旧海軍佐世保鎮守府凱旋記念館）","kana":"させぼしみんぶんかほーる（きゅうかいぐんさせぼちんじゅふがいせんきねんかん）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市平瀬町２","lat":33.17374274,"lng":129.71490706,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建，鉄板葺，建築面積826㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"42 － 0007","desc":"第１次世界大戦の鎮守府所属艦船の武勲をたたえるため，九州・四国各県の寄付で建設された。鉄筋コンクリート造２階建で，妻を正面にみせた左右対称の外観，１・２階を通した柱，幾何学的な装飾等に特徴がある。海軍ゆかりの町の象徴として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000420"},{"id":"00009560","register_sub_id":"101","register_pk":"194353","name":"島原城御馬見所","kana":"しまばらじょうおんうまみしょ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県島原市城内1-1183-1","lat":32.7895347,"lng":130.36754766,"geo_status":"db","era":"江戸末期／明治前期・昭和41年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、杉皮葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"42 － 0103","desc":"島原城の本丸、天守の北東側に西面して建つ。桁行六・九メートル梁間三・四メートル、切妻造杉皮葺で、四畳半二室を畳廊下の南北に配し、西面を開放する。もとは三の丸の調練所に所在し、藩主が藩士の訓練状況視察に使用した。近世の馬見所として希な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009560"},{"id":"00010382","register_sub_id":"101","register_pk":"199154","name":"仙禽庫","kana":"せんきんこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘13-3","lat":33.373236,"lng":129.553111,"geo_status":"db","era":"江戸末期／明治前期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積126㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0120","desc":"松浦史料博物館の北方に金剛庫と並んで東西棟で南面して建つ。二階建の土蔵で、桁行六間梁間二間半、寄棟造桟瓦葺、平入とし、正面入口に下屋を設ける。床高が高く、防湿に配慮されており、平戸城内の文庫を移築したという伝承に相応しい仕様となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010382"},{"id":"00002342","register_sub_id":"101","register_pk":"103332","name":"旧佐伯海軍航空隊掩体壕","kana":"きゅうさえきかいぐんこうくうたいえんたいごう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県佐伯市東浜1-6","lat":32.96908759,"lng":131.91636403,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造、建築面積225㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0068","desc":"面積２２５㎡の鉄筋コンクリート造で，矩形の開口部で縁取ったヴォールト構造部分の後方に，尾翼を収納するためのほぼ半円筒状の構造体が付く特徴的な形態をもつ。戦時耐弾構造物の一例で，旧海軍航空機の防空用格納施設として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002342"},{"id":"00012267","register_sub_id":"101","register_pk":"353068","name":"細島験潮場","kana":"ほそしまけんちょうじょう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県日向市大字細島（細島商業港）","lat":32.428627,"lng":131.669579,"geo_status":"db","era":"明治26年／大正12年・昭和13年改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積6.1㎡","structure_material":"煉瓦造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"45-93","desc":"継続的な潮位観測のため陸地測量部によって設置された験潮場の建屋。現在の建屋は明治二六年のもの。切妻造妻入の煉瓦造で、屋根は桟瓦葺。内部は前室と観測室からなり、観測室に井戸が設けられている。我が国における潮位観測の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012267"},{"id":"00006565","register_sub_id":"101","register_pk":"107548","name":"旧陸軍知覧飛行場弾薬庫","kana":"きゅうりくぐんちらんひこうじょうだんやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17919-1","lat":31.36138709,"lng":130.43483764,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.7㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0042","desc":"旧知覧飛行場（現知覧平和公園）の北東に造られ，桁行２．８ｍ，梁間２．４ｍ，壁厚２６ｃｍの規模で，鉄筋コンクリート造平屋建とする。木造の切妻屋根とし，内壁を板張としていた。小規模であるが，当時の弾薬庫の特徴を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006565"},{"id":"00006564","register_sub_id":"101","register_pk":"107547","name":"旧陸軍知覧飛行場着陸訓練施設鎮碇","kana":"きゅうりくぐんちらんひこうじょうちゃくりくくんれんしせつちんてい","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17885-3","lat":31.36389961,"lng":130.43302495,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造、高さ2.3m、面積70㎡","structure_material":"鉄筋コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0043","desc":"旧知覧飛行場（現知覧平和公園）の西方に造られた，着陸訓練用のロープを固定したＲＣ造の鎮碇である。南北１０ｍ，東西６ｍの床部を築き，中央やや西寄りに脚部２つを立て，ロープを固定した梁で両者を繋ぐ。当時の飛行訓練施設の状況を知る貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006564"},{"id":"00006566","register_sub_id":"101","register_pk":"107549","name":"旧陸軍知覧飛行場防火水槽","kana":"きゅうりくぐんちらんひこうじょうぼうかすいそう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17932","lat":31.36037553,"lng":130.43561204,"geo_status":"db","era":"昭和16／平成16移設","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"コンクリート造、面積93㎡","structure_material":"コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0041","desc":"旧知覧飛行場（現知覧平和公園）の北東に造られたコンクリート造の防火水槽である。直径１０ｍの円形で，周囲を１ｍ立ち上げ，すり鉢状で中央の深さを２ｍとし，底面に中央に向かって３方向から階段を付ける。往時の飛行場施設のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006566"},{"id":"00002343","register_sub_id":"101","register_pk":"103333","name":"仙巌園内濾過池","kana":"せんがんえんないろかち","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市吉野町9700-1","lat":31.6189988,"lng":130.58152083,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造平屋建、建築面積21㎡、深さ2.4m","structure_material":"石造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0007","desc":"市街の北部，鹿児島湾を臨む名勝仙巌園の隣接地に所在する。地下約２．４ｍの位置に布設された水道石管から取水し，ろ過の後に敷地内各所に配水する。大型切石積の壁面から石造ヴォールト天井を架け，外観は和風を意識した切妻屋根に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002343"},{"id":"00002345","register_sub_id":"101","register_pk":"103335","name":"山田の凱旋門","kana":"やまだのがいせんもん","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市下名1178","lat":31.77358119,"lng":130.61411907,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"石造、高さ4.7m、幅4.9m","structure_material":"石造","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0009","desc":"日露戦争従軍者の帰還を記念して山田村兵事会が建設。江戸切仕上の石を１５段，高４．７ｍに積んで門柱とし，約２．７ｍの門柱間に石アーチを架けて凱旋門風の構えを造る。小規模ながら，日本では類例の少ない恒久的凱旋門建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002345"}];
